-- =====================================================================
-- LISTADO DE ARTICULOS - LA VALENCIANA MATERIALES PARA LA CONSTRUCCION SAS
-- Origen : articulos_general_factor.xls (reporte del 09/09/2026)
-- Filas  : 15379
-- Motor  : PostgreSQL (sintaxis compatible con MySQL/MariaDB salvo donde se indica)
-- =====================================================================

BEGIN;

DROP TABLE IF EXISTS articulos;

CREATE TABLE articulos (
    codigo        VARCHAR(20)   PRIMARY KEY,           -- texto: hay ceros a la izquierda y sufijos (000046-1)
    descripcion   VARCHAR(250)  NOT NULL,
    und_base      VARCHAR(10),                         -- NULL en cuentas de gasto sin unidad
    und_alt       VARCHAR(10),
    factor        NUMERIC(12,2) NOT NULL DEFAULT 1
                  CHECK (factor > 0),                  -- unidades base por unidad alterna (p.ej. 1 CAJA = 250 UND)
    fecha_ultima  DATE                                 -- NULL si el origen traia 30/12/1899 (fecha nula de Excel)
);

CREATE INDEX idx_articulos_descripcion ON articulos (descripcion);
































COMMIT;
